// Read rows failed (network/quota/permission error on the sheet). Stop here — do not
// attempt to normalize or write anything on top of a run that never got real data.
const out = [];
for (const item of $input.all()) {
  out.push({ json: { logged: 'read-failed', at: new Date().toISOString(), error: item.json.error || item.json } });
}
return out;

// Normalizes three common messy columns without touching the rest of the row.
// Adjust the column names (PHONE_COL, EMAIL_COL, DATE_COL) to match your sheet.
const PHONE_COL = 'phone';
const EMAIL_COL = 'email';
const DATE_COL = 'date';
const DEFAULT_COUNTRY_PREFIX = '+1'; // change to your default country code

function cleanPhone(raw) {
  if (!raw) return '';
  let digits = String(raw).replace(/[^0-9+]/g, '');
  if (!digits.startsWith('+')) digits = DEFAULT_COUNTRY_PREFIX + digits.replace(/^0+/, '');
  return digits;
}
function cleanEmail(raw) {
  if (!raw) return '';
  return String(raw).trim().toLowerCase();
}
function isValidEmail(e) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
}
function cleanDate(raw) {
  if (!raw) return '';
  const d = new Date(raw);
  if (isNaN(d.getTime())) return '';
  return d.toISOString().slice(0, 10); // YYYY-MM-DD
}

const out = [];
for (const item of $input.all()) {
  const row = { ...item.json };
  const originalPhone = row[PHONE_COL];
  const originalEmail = row[EMAIL_COL];
  const originalDate = row[DATE_COL];
  row[PHONE_COL] = cleanPhone(originalPhone);
  row[EMAIL_COL] = cleanEmail(originalEmail);
  row[DATE_COL] = cleanDate(originalDate);
  row._email_valid = isValidEmail(row[EMAIL_COL]);
  row._changed = row[PHONE_COL] !== originalPhone || row[EMAIL_COL] !== originalEmail || row[DATE_COL] !== originalDate;
  row._reason = row._email_valid ? '' : 'invalid email after cleanup';
  out.push({ json: row });
}
return out;

// The sheet write failed (quota, locked range, permission). Log it explicitly instead of
// letting it disappear — the source data is untouched, safe to retry next run.
const out = [];
for (const item of $input.all()) {
  out.push({ json: { logged: 'write-failed', at: new Date().toISOString(), error: item.json.error || item.json } });
}
return out;
